db->prepare("SELECT * FROM `{$this->types_table}` ORDER BY id DESC LIMIT %d OFFSET %d",$per_page,$offset),ARRAY_A);$total=(int)$wpdb->get_var("SELECT COUNT(*) FROM `{$this->types_table}`");}return['items'=>$items?:[],'total'=>$total,];}public function get_type_by_id(int $id): ?array{global $wpdb;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM `{$this->types_table}` WHERE id = %d",$id),ARRAY_A);return $row?:null;}public function create_type(string $name,string $slug){global $wpdb;$name=sanitize_text_field($name);$slug=sanitize_title($slug);if($this->slug_exists($slug)){return new WP_Error('leb_duplicate_slug',__('A type with this slug already exists.','listing-engine-backend'));}$inserted=$wpdb->insert($this->types_table,['name'=>$name,'slug'=>$slug,'updated_at'=>current_time('mysql'),],['%s','%s','%s']);if(false===$inserted){return new WP_Error('leb_insert_failed',__('Failed to create the type. Please try again.','listing-engine-backend'));}return(int)$wpdb->insert_id;}public function update_type(int $id,string $name,string $slug){global $wpdb;$name=sanitize_text_field($name);$slug=sanitize_title($slug);if($this->slug_exists($slug,$id)){return new WP_Error('leb_duplicate_slug',__('A type with this slug already exists.','listing-engine-backend'));}$updated=$wpdb->update($this->types_table,['name'=>$name,'slug'=>$slug,'updated_at'=>current_time('mysql'),],['id'=>$id],['%s','%s','%s'],['%d']);if(false===$updated){return new WP_Error('leb_update_failed',__('Failed to update the type. Please try again.','listing-engine-backend'));}return true;}public function delete_type(int $id){global $wpdb;$deleted=$wpdb->delete($this->types_table,['id'=>$id],['%d']);if(false===$deleted){return new WP_Error('leb_delete_failed',__('Failed to delete the type. Please try again.','listing-engine-backend'));}return true;}public function delete_types(array $ids){global $wpdb;if(empty($ids)){return true;}$ids_placeholder=implode(',',array_fill(0,count($ids),'%d'));$query=$wpdb->prepare("DE